                if (EntityBlueJay.this.timeFlying < 200 || EntityBlueJay.this.isOverWaterOrVoid()) {
                    return EntityBlueJay.this.getBlockInViewAway(vector3d, 0);
                } else {
                    return EntityBlueJay.this.getBlockGrounding(vector3d);
